function addChapter(id, title, paragraphs) {
  const heading = { type: "heading", text: title, eventId: id, sourcePage: BOOK_DATA.toc.length + 2 };
  BOOK_DATA.events.push(heading);
  BOOK_DATA.toc.push({ title, eventId: id, sourcePage: heading.sourcePage });
  paragraphs.forEach((item, index) => {
    if (typeof item === "string") {
      BOOK_DATA.events.push({ type: "text", text: item, eventId: `${id}-p${index + 1}`, sourcePage: heading.sourcePage });
    } else {
      BOOK_DATA.events.push({ type: "image", src: item.src, alt: item.alt, pixelWidth: item.width, pixelHeight: item.height, large: true, eventId: `${id}-i${index + 1}`, sourcePage: heading.sourcePage });
    }
  });
}

function addIllustrationAfter(anchorId, eventId, src, alt, width = 1122, height = 1402) {
  const index = BOOK_DATA.events.findIndex(event => event.eventId === anchorId);
  if (index < 0) throw new Error(`Illustration anchor not found: ${anchorId}`);
  const anchor = BOOK_DATA.events[index];
  BOOK_DATA.events.splice(index + 1, 0, {
    type: "image", src, alt, pixelWidth: width, pixelHeight: height,
    large: true, eventId, sourcePage: anchor.sourcePage
  });
}

addChapter("c1", "I · O Primeiro Dia", [
  "O choro chegou antes da luz. Lá fora, a madrugada ainda segurava o frio nas pedras; dentro do quarto, uma lamparina tornava douradas as mãos que recebiam o recém-nascido. Não houve presságio, trovão ou sinal no céu. Houve apenas o fôlego curto de uma criança e o silêncio atento dos adultos ao redor.",
  "A mãe de Draven parecia exausta demais para sorrir e alerta demais para dormir. Mantinha os olhos no menino como quem já começava a medir o mundo que tentaria alcançá-lo. O pai, ao lado, vestia um casaco escuro de corte preciso, fechado por pequenos encaixes metálicos que se ajustavam sem fivela aparente. As mangas estavam arregaçadas e havia uma mancha de sangue seco no punho. Quando lhe entregaram a criança, segurou-a com uma cautela que contrastava com os ombros largos.",
  { src: "assets/draven/draven-nascimento.jpg", alt: "O pai original de Draven segura o recém-nascido; a mãe de origem oriental permanece ao lado", width: 1024, height: 1536 },
  "Draven abriu os olhos. Vermelhos, ainda turvos, encontraram o rosto do pai por um instante. O homem não procurou semelhanças. O cabelo do menino era claro, quase branco sob a chama; o dele, escuro, ondulado e preso atrás da nuca. A mãe tinha longos cabelos prateados trançados sobre o ombro; as mangas bordadas de sua roupa oriental traziam formas que pertenciam à sua própria herança. Nenhum dos dois parecia uma versão adulta do filho.",
  "— Ele está olhando para você — disse a mãe.",
  "— Está olhando para a lamparina.",
  "— Então já escolheu o que merece atenção.",
  "O pai baixou os olhos para o bebê. Por um breve momento, a dureza do seu rosto cedeu, mas não chegou a se desfazer. A mãe estendeu um dedo; Draven fechou a mão minúscula em torno dele, sem força para prender coisa alguma. A manga bordada dela trazia linhas que o pai não usaria e que, um dia, o menino reconheceria nas histórias enviadas de longe.",
  "Ninguém prometeu que a vida seria fácil. Ninguém falou de destino. O nome foi dito uma vez, com a firmeza de algo que passaria a pertencer ao mundo: Draven Dark. Pelo pai, o menino herdava o nome da linhagem; o restante de sua identidade ainda teria de ser escolhido. Uma lente de diagnóstico, embutida num braço de latão ao lado da cama, registrou os sinais do recém-nascido sem interromper a conversa. O pai conferiu a leitura; a mãe corrigiu a posição de uma manta. A técnica era tão cotidiana quanto a água quente e os lençóis limpos.",
  "Quando a luz enfim atravessou a janela, o pai ainda segurava Draven. A mãe ficou ao lado deles, as vestes orientais intactas, sem que ninguém as tratasse como curiosidade. Entre os três havia diferenças de rosto, cabelo e origem; a semelhança do menino com os dois ainda era promessa, não retrato. Lá fora, o dia começava sem conhecer a linhagem, as disputas ou a ambição da criança."
]);

addChapter("c2", "II · A Faísca e a Disciplina", [
  "A lembrança mais antiga de Draven sobre o treinamento não era uma lição. Era o gosto de terra na boca. Ele tinha seis anos, joelhos sujos e as duas mãos fechadas de raiva porque os outros meninos já haviam atravessado o pátio antes dele. O instrutor mandou que voltasse ao começo. Draven voltou. Não porque aceitasse a ordem; porque queria chegar primeiro na tentativa seguinte.",
  "O território era grande o bastante para a infância parecer sem fronteiras. Florestas escuras fechavam o horizonte em alguns pontos; mais perto, casas de pedra e madeira se agrupavam em torno de caminhos batidos. As estruturas de treino serviam ao uso diário. Algumas peças de metal se ajustavam com precisão incomum, mas nada brilhava para chamar atenção. A vida seguia entre chuva, refeições, trabalho e exercícios.",
  "Naquela manhã, o grupo recebeu uma tarefa pequena: manter entre as mãos uma centelha de luz aquecida, sem deixá-la apagar nem crescer. O instrutor demonstrou uma vez. Draven tentou antes do fim da explicação. A primeira tentativa não produziu nada. Na segunda, uma luz fraca tremeu entre seus dedos e morreu quando ele sorriu para os meninos que olhavam. Sob o piso, faixas de leitura registravam o tempo e a variação do exercício; o instrutor consultava os dados num mostrador de vidro escuro embutido na parede, sem interromper a aula.",
  { src: "assets/draven/draven-sete-anos.jpg", alt: "Draven aos sete anos tenta manter uma centelha mágica simples entre as mãos em um salão de treino tecnologicamente avançado", width: 1122, height: 1402 },
  "— De novo — disse o instrutor.",
  "— Eu já fiz.",
  "— E já perdeu.",
  "Draven estreitou os olhos. Recomeçou sem olhar para os outros. A centelha apareceu menor, quase tímida, e persistiu o tempo de três respirações. Depois se apagou. Ele franziu a testa, mas havia entendido o suficiente para querer mais: não a luz em si, e sim o fato de que sua vontade ainda não bastava para mantê-la.",
  "A magia entrou na rotina antes que ele soubesse chamá-la de vocação. Havia exercícios simples para sentir o esforço, repetir um gesto e reconhecer o próprio limite. Nada surgia pronto. Se Draven se distraía, a centelha sumia. Se forçava, os dedos tremiam e o instrutor encerrava a prática. O menino detestava a pausa obrigatória. Detestava ainda mais que ela funcionasse.",
  "À tarde, o mesmo pátio recebia treino de equilíbrio e passos. Draven caiu duas vezes. Na terceira, terminou a travessia sem tocar o chão com as mãos. Contou o resultado em voz alta, para que ninguém pudesse fingir que não vira. Um dos meninos respondeu com um encolher de ombros. Draven guardou a indiferença como se fosse um insulto.",
  "Naquela semana, um estojo selado chegou pela caixa de comunicação do alojamento. Dentro havia uma carta da mãe. Não era longa. Ela contava uma lembrança de sua infância: tecidos guardados para ocasiões específicas, desenhos que mudavam conforme a mão e a estação, e a irritação que sentia quando um adulto chamava de inútil tudo o que não podia ser medido. Não nomeava uma nação ou clã; falava de sua própria vida.",
  "Draven leu uma vez, depois outra, em silêncio. Dobrou a carta com precisão e guardou-a entre as páginas do caderno de exercícios, como se o papel precisasse de proteção contra a umidade. Na manhã seguinte, quando um menino chamou a centelha de brincadeira, Draven respondeu que ao menos a brincadeira obedecia melhor que ele. Não mencionou a carta.",
  "À noite, quando os músculos começaram a doer, tentou refazer a centelha sozinho. A luz surgiu por um segundo e apagou. Ele tentou outra vez. O instrutor passou pela porta, viu o brilho breve e não entrou.",
  "— Amanhã — falou do corredor.",
  "Draven não respondeu. Esperou que os passos se afastassem e tentou mais uma vez. A mão tremeu. A centelha falhou. Só então ele fechou os dedos, irritado, e foi dormir com a certeza de que no dia seguinte tentaria de novo."
]);

addChapter("c3", "III · O Gosto da Vitória", [
  "Aos nove anos, Draven já aprendera que uma vitória podia ser pequena e ainda assim deixar alguém furioso. Na disputa de bastões de madeira, venceu por pouco. Não foi mais forte que o outro menino, nem mais rápido em todos os movimentos. Percebeu que o adversário repetia a mesma defesa quando recuava e esperou até que o hábito se tornasse previsível.",
  "O pátio estava úmido da chuva da noite. Os bastões escorregavam nas mãos; os meninos em volta formavam um círculo irregular, quietos demais para fingir que não se importavam. O instrutor percorreu as regras mais uma vez: sem golpes na cabeça, sem continuar depois do sinal. Draven confirmou com um aceno impaciente. Queria que começassem.",
  "No primeiro avanço, perdeu terreno. O adversário empurrou o bastão contra o seu e quase o desequilibrou. Draven recuou, sentindo o impacto subir pelos braços. Em vez de responder com força, deixou o outro acreditar que o havia encurralado. Quando veio o segundo golpe, Draven girou para fora da linha, bateu no punho que segurava a arma e tocou o bastão no peito do rival.",
  { src: "assets/draven/draven-nove-anos.jpg", alt: "Draven comemora uma vitória comum no treino enquanto o instrutor interrompe a provocação", width: 1122, height: 1402 },
  "O sinal encerrou a disputa. O outro menino sentou-se na lama, contrariado, sem ferimentos. Draven ficou de pé, ofegante, com um sorriso que não tentou esconder.",
  "— Era só não repetir o mesmo movimento — disse. — Ficou fácil.",
  "O menino no chão ergueu os olhos. Draven viu a raiva e decidiu que preferia vê-la a receber um agradecimento. O instrutor avançou entre os dois antes que a resposta virasse outra disputa.",
  "— Você venceu a luta — disse ele. — Não precisa inventar uma segunda para provar que venceu.",
  "Draven baixou o bastão, mas demorou a baixar o queixo. Não pediu desculpas. Também não repetiu a provocação quando o outro se levantou. O silêncio não era arrependimento; era cálculo. O instrutor mandou que recolhessem as armas e voltassem à fila. Draven obedeceu por fim, ainda irritado por a vitória não lhe dar a última palavra.",
  "Mais tarde, repetiu para si mesmo a sequência que dera certo. O passo lateral. O golpe no punho. O toque no peito. Podia ter vencido por acaso, mas não queria depender disso. A lembrança que levou consigo não foi a cara do menino na lama; foi o instante em que percebeu o padrão e escolheu esperar.",
  "Naquele dia, Draven conquistou uma pequena vitória e descobriu que ela não apagava o limite imposto pelo instrutor, nem obrigava o adversário a gostar dele. Ainda assim, quando o treino terminou, foi o primeiro a pedir outra disputa. Não queria que a tarde acabasse enquanto alguém pudesse ser melhor do que ele."
]);

addChapter("c4", "IV · A Derrota Pública", [
  "Aos dez anos, Draven já aprendera a reconhecer o momento em que os outros começavam a esperar que ele vencesse. A prova daquela manhã parecia simples: completar o percurso de resistência e tocar o marcador antes dos demais. Trilhos finos, assentados sob a pedra, registravam tempo e ritmo. Um mostrador escuro junto à arquibancada recebia as leituras sem que ninguém precisasse correr atrás de uma ampulheta.",
  "Draven partiu depressa. O primeiro trecho lhe deu vantagem; no segundo, ele a gastou tentando ampliá-la. O caminho estreitou entre duas paredes de pedra. O menino à frente encontrou a passagem sem quebrar o ritmo. Draven tentou ultrapassá-lo pelo lado de fora, perdeu segundos numa curva e chegou ao marcador depois dele.",
  { src: "assets/draven/draven-dez-anos.jpg", alt: "Draven aos dez anos termina uma prova comum em segundo lugar e tenta se recompor", width: 1122, height: 1402 },
  "O outro garoto já havia parado quando Draven cruzou a linha. Não ergueu os braços nem provocou. Aquilo irritou Draven mais do que uma comemoração teria irritado.",
  "— Você olhou para trás — disse Draven, puxando o ar. — Perdeu tempo.",
  "— Mesmo assim cheguei antes.",
  "Draven abriu a boca, procurando uma resposta que não parecesse desculpa. O instrutor chamou os dois para o mostrador. As linhas de tempo confirmaram o resultado e também indicaram onde Draven perdera velocidade. Não havia erro no registro para contestar. A prova simplesmente terminara.",
  "Ele encarou o marcador como se a máquina tivesse escolhido um lado. O instrutor explicou os trechos, sem elevar a voz. Draven ouviu até o fim, não por obediência, mas porque precisava descobrir exatamente onde o outro fora melhor. Depois pediu os dados completos. O instrutor deixou que consultasse o registro por alguns minutos.",
  "— Vai tentar de novo? — perguntou o adversário.",
  "— Quando você estiver menos satisfeito consigo mesmo.",
  "A resposta saiu afiada o bastante para ferir, mas não para apagar a derrota. O menino se afastou sem aceitar o convite nem a provocação. Draven não o seguiu. Passou o restante da manhã reconstituindo o percurso na cabeça: a curva, o espaço perdido, a pressa que confundira velocidade com controle.",
  "À tarde, voltou à centelha entre as mãos. Conseguiu mantê-la acesa por três passos lentos antes que o movimento a desfizesse. Não era uma vitória que pudesse anunciar. Para ele, bastava como evidência: havia um jeito de aprender a sustentar o que ainda lhe escapava. Guardou o resultado para si e pediu outra tentativa para o dia seguinte."
]);

addChapter("c5", "V · Cartas do Lado de Fora", [
  "A carta seguinte chegou pelo relé de comunicação do alojamento, lacrada e seca apesar da chuva. O estojo de parede acendeu três pontos âmbar; um dos homens responsáveis pela distribuição retirou o envelope e chamou Draven pelo nome. Nenhuma mulher vivia ou treinava ali. A voz da mãe chegava em papel, à distância, e o menino aprendera a reconhecer a letra antes mesmo de abrir a dobra.",
  "Aos onze anos, já tinha cartas guardadas dentro do caderno. Não as exibia e tampouco admitia que esperava por elas. Naquela, a mãe descrevia uma parte de sua origem sem nomear país, clã ou linhagem. Falava do peso de certos tecidos, de desenhos feitos à mão e de como uma roupa podia mudar a maneira de atravessar uma sala — não por magia, dizia ela, mas pela decisão de quem a vestia.",
  { src: "assets/draven/draven-onze-anos-carta.jpg", alt: "Draven lê uma carta da mãe no território masculino, junto a um pequeno retalho e referências desenhadas", width: 1122, height: 1402 },
  "Com a carta vinha um retalho de tecido bordado. Não era um símbolo de família nem uma marca de poder. A mãe explicava que o escolhera porque gostava do desenho e da forma como a linha escura quebrava o campo vermelho. Acrescentava uma opinião sobre um assunto que não tinha relação com Draven: não suportava que transformassem gosto em obrigação, nem tradição em desculpa para mandar na vida alheia.",
  "Draven leu essa parte duas vezes. Depois dobrou o papel seguindo as marcas originais, alinhou o retalho com a folha e guardou ambos no caderno. Um colega viu o tecido quando ele fechava a capa.",
  "— Vai usar isso?",
  "— Vou decidir quando você parar de perguntar.",
  "O garoto riu e foi cuidar dos próprios exercícios. Draven enfiou o caderno sob o braço, irritado por ter sido observado. Naquela noite, abriu a carta uma terceira vez. Não porque concordasse com tudo; algumas frases pareciam escritas para alguém mais velho, e ele não gostava de receber instruções disfarçadas de histórias. Mas a mãe não falava com ele como se fosse uma criança sem opinião. Isso ele respeitava, embora não o dissesse.",
  "No dia seguinte, escolheu uma faixa de tecido escuro para prender o próprio cabelo durante o treino. O retalho da carta ficou guardado. Draven não tentou copiar o bordado e não vestiu uma identidade pronta. Pegou apenas a ideia de que uma escolha podia ser sua — e que ninguém precisava aprová-la para que valesse.",
  "Ao fim da semana, pediu acesso ao registro do relé para saber quando chegaria a próxima remessa. O encarregado ergueu uma sobrancelha. Draven corrigiu a postura e acrescentou que precisava da informação para organizar os exercícios. Não mencionou o envelope. O indicador âmbar piscou no mesmo ritmo de sempre, indiferente à explicação."
]);

addChapter("c6", "VI · Além dos Portões", [
  "Aos doze anos, Draven saiu do território acompanhado por um homem adulto e dois rapazes da mesma formação. A viagem tinha um propósito limitado: acompanhar a entrega de equipamento e conhecer parte da infraestrutura que servia às comunidades do entorno. Não era uma expedição de conquista. O guia repetiu isso quando Draven perguntou se haveria algo digno de contar na volta.",
  "— Se precisa de perigo para prestar atenção, vai aprender pouco — respondeu o homem.",
  "Draven não gostou da frase. Continuou andando mesmo assim.",
  "A estrada atravessava uma garganta entre colinas. Pedra clara, reforçada por ligas escuras, sustentava um sistema de transporte por cabos e contrapesos. Uma cabine fechada avançava sobre o vale em trilhos suspensos, sem ruído além do atrito controlado das rodas. As luzes de posição mudavam quando o mecanismo travava o próximo trecho. Não havia feitiço naquele movimento; havia engenharia mantida por gente que sabia o que fazia.",
  { src: "assets/draven/draven-doze-anos-viagem.jpg", alt: "Draven aos doze anos cruza uma ponte de transporte mecanizada em viagem acompanhada", width: 1122, height: 1402 },
  "Draven parou para observar os contrapesos. O guia continuou até perceber que o grupo se alongara. Um dos rapazes riu quando Draven voltou ao passo, como se a curiosidade o tivesse atrasado.",
  "— Você olha para cada engrenagem como se pudesse vencê-la — disse o rapaz.",
  "— Se ela estivesse competindo comigo, eu venceria.",
  "— Ela já está levando você para onde quer.",
  "Draven guardou a resposta. O comentário tinha sido insolente e, por isso, difícil de descartar. Na cabine, examinou o fecho da porta, as juntas da estrutura e a sequência das luzes. Quando a parada seguinte atrasou, notou que a terceira lâmpada permanecia apagada. O guia verificou a leitura num instrumento de mão e confirmou a espera; não havia falha, só uma manutenção em andamento. Draven não descobriu nada que os adultos não soubessem. Ainda assim, percebeu que tinha aprendido a olhar.",
  "Do outro lado, a paisagem se abriu em terraços de cultivo, canais cobertos e oficinas cuja força vinha de mecanismos escondidos sob a pedra. Pessoas atravessavam pontes, transportavam carga e ajustavam equipamentos como parte da vida diária. A civilização não abandonara as formas antigas; havia aprendido a fazer mais com elas.",
  "Na entrega, Draven carregou uma caixa pequena sem pedir ajuda. O rapaz que o provocara segurou a outra ponta quando o peso começou a pender. Draven aceitou a mão sem agradecer, depois corrigiu o nó da alça para que não tornasse a escorregar. A cooperação durou menos que a irritação dos dois, mas funcionou.",
  "Na volta, Draven fez perguntas sobre o mecanismo, os intervalos de manutenção e quem decidia a prioridade dos reparos. O guia respondeu ao que podia sem transformar a viagem numa aula. Draven discutiu duas respostas e guardou as outras. Não voltou mais poderoso nem mais experiente em combate. Voltou com uma escala maior para medir o mundo — e com a certeza de que havia muito mais que podia aprender, se encontrasse um jeito de fazer isso render a seu favor."
]);

addChapter("c7", "VII · A Cidade em Movimento", [
  "Draven tinha treze anos quando voltou a sair do território e percebeu que a primeira viagem não lhe ensinara quase nada sobre uma cidade. Desta vez, tentou olhar para o conjunto: os canais cobertos sob a rua, os elevadores de carga escondidos em torres de pedra, as lanternas que ajustavam a luz sem fumaça e as estações de comunicação encaixadas nas paredes dos edifícios.",
  "O grupo caminhava com um guia adulto. Draven acompanhava as engrenagens acima das portas e as linhas metálicas que marcavam os caminhos de transporte. Queria saber o que movia cada peça. Quando o guia respondeu que algumas perguntas precisavam de mais tempo do que a visita permitia, Draven sorriu como se tivesse vencido uma disputa.",
  { src: "assets/draven/draven-treze-anos-cidade.jpg", alt: "Draven aos treze anos examina um instrumento de orientação numa cidade medieval com infraestrutura avançada", width: 1122, height: 1402 },
  "Perto de uma plataforma de carga, um mecanismo parou entre dois níveis. Um trabalhador conferiu as marcas no mostrador e pediu que aguardassem. Draven apontou para um indicador lateral que seguia aceso.",
  "— Esse diz que o próximo trecho está livre.",
  "— Diz que o circuito recebeu energia — corrigiu o guia. — Não que o peso já foi travado.",
  "Draven examinou as duas leituras e percebeu o segundo sinal, menor e quase escondido sob uma moldura. Não respondeu. Quando a plataforma enfim se moveu, acompanhou o contrapeso até perder a vista dele. A máquina não o impressionava por ser grande, mas por depender de gente que conhecia os seus limites e fazia a manutenção antes da falha.",
  "Nas cartas mais recentes, a mãe descrevera como escolhia o que vestir quando queria ser vista e o que vestia quando preferia observar. Draven releu uma dessas linhas antes da viagem e amarrou à alça da própria bolsa uma estreita faixa carmesim. Não copiara o traje dela. Escolhera um detalhe que gostava de ver em movimento.",
  "O guia notou a faixa e perguntou se ela tinha função. Draven olhou para a própria roupa.",
  "— Tem. Eu escolhi.",
  "— Então já serve para alguma coisa.",
  "A resposta não foi elogio nem reprimenda. Draven quase procurou um tom escondido nela, mas desistiu. No caminho de volta, acertou a leitura de uma placa de orientação e venceu por pouco um dos rapazes numa corrida curta até a próxima arcada. A cidade não se curvou à sua curiosidade; ainda assim, ele voltou com perguntas melhores do que as que trouxera."
]);

addChapter("c8", "VIII · Um Rival à Altura", [
  "Aos quatorze anos, Draven queria que a magia obedecesse à mesma lógica de uma disputa física: perceber o hábito do outro, escolher o instante e tomar a dianteira. O exercício daquele dia não permitia pressa. Cada participante devia manter uma luz comum entre as mãos enquanto atravessava uma sequência curta de marcas no chão. As faixas de leitura registrariam estabilidade, tempo e interrupções.",
  "O colega que vencera Draven na prova de percurso aceitou participar. Os dois tinham aprendido a reconhecer os movimentos um do outro, ainda que nenhum chamasse isso de amizade. A prática começaria em lados opostos do salão e terminaria numa marca circular embutida no piso. Não havia golpe ou feitiço de ataque. Bastava manter a centelha acesa e chegar ao final.",
  "Draven soltou o ar e fechou os dedos ao redor da luz sem tocá-la. O colega partiu num ritmo mais lento. Draven acelerou no segundo trecho. A chama dele vacilou, recuperou-se e tornou a oscilar quando tentou corrigir o passo sem perder velocidade.",
  { src: "assets/draven/draven-c8-disputa-cabelo-continuidade-corrigida-2026.webp", alt: "Draven e o colega aos quatorze anos disputam um exercício mágico básico; cabelo branco em comprimento intermediário, sem tatuagens", width: 1122, height: 1402 },
  "O rapaz chegou à marca primeiro. A luz dele continuava pequena e estável. A de Draven ainda ardia, mas tremia o bastante para registrar uma interrupção. Ele olhou para a própria mão, depois para o círculo sob o pé do outro.",
  "— Você foi devagar.",
  "— E terminei antes.",
  "Draven poderia ter discutido a medida ou acusado a leitura. O mostrador já apresentava os dados, claros para quem quisesse consultá-los. Ele caminhou até a marca, fez a luz se apagar e cruzou os braços.",
  "— Na próxima, eu escolho o ritmo.",
  "— Na próxima, tenta não correr contra a própria mão.",
  "O comentário encontrou o orgulho de Draven antes que ele pudesse se preparar. Por um instante, seu sorriso virou uma ameaça de resposta cruel. Ele conteve a frase. Não por gentileza: queria outra tentativa e precisava que o outro continuasse disposto a competir.",
  "A ficha do exercício registrou a vitória do colega por estabilidade e tempo. Draven decorou os números e pediu uma repetição para o dia seguinte. O instrutor aprovou a prática, não a revanche. Ainda assim, quando o adversário aceitou, Draven saiu do salão convencido de que a disputa tinha apenas começado."
]);

addChapter("c9", "IX · O Preço de Provocar", [
  "No dia seguinte, Draven voltou ao salão antes do horário. Encontrou o colega perto dos mostradores, conferindo os registros da prática. Em vez de perguntar se ele queria repetir o exercício, Draven comentou que uma única vitória não provava nada. O tom foi calculado para arrancar resposta dos rapazes que se reuniam perto da entrada.",
  "— Você escolheu o ritmo, eu escolhi não desperdiçar esforço — respondeu o colega. — Se quer outra tentativa, pede outra tentativa.",
  "As risadas vieram de dois lados do salão. Draven inclinou a cabeça, como se o comentário tivesse sido esperado. Por dentro, detestava que o outro tivesse transformado a conversa em regra pública. Deu um passo para perto, mas o rapaz recolheu as fichas e foi para a outra estação, sem desafio ou ameaça.",
  { src: "assets/draven/draven-quatorze-anos-consequencia.jpg", alt: "Draven aos quatorze anos encara as consequências de sua provocação enquanto o colega se afasta", width: 1122, height: 1402 },
  "A próxima atividade exigia trabalho em pares: alternar a condução de uma luz fraca e usar os sinais do companheiro para corrigir o próprio ritmo. Draven perguntou ao colega se fariam juntos. Recebeu um não simples, sem explicação. A recusa não era punição oficial; era escolha de alguém cansado de ser tratado como plateia.",
  "O instrutor designou outro parceiro. Draven completou a tarefa, mas gastou mais tempo para estabelecer um ritmo comum. A luz apagou uma vez. Ele começou a culpar o erro do outro menino e parou antes de dizê-lo. O exercício era dos dois. A leitura do mostrador não permitia transferir metade da falha.",
  "Quando a sessão terminou, Draven encontrou o primeiro colega perto da porta. Poderia ter fingido que não se importava. Em vez disso, ofereceu uma condição concreta.",
  "— Você escolhe a sequência na próxima prática. Eu escolho a seguinte.",
  "— E sem comentário para a arquibancada.",
  "Draven passou o polegar pela faixa carmesim presa à sua alça. A carta da mãe lhe voltara à lembrança: gosto não era obrigação, e tradição não era autorização para mandar nos outros. Ele não achava que a frase se aplicasse a tudo. Mas aquele colega não lhe devia uma disputa.",
  "— Sem plateia — respondeu.",
  "O rapaz não sorriu nem ofereceu amizade. Concordou com um aceno e seguiu caminho. Draven ficou no salão por mais alguns minutos, repetindo sozinho o exercício que ainda não dominava. A provocação lhe rendera atenção e lhe custara um parceiro. Ele continuava querendo vencer; pela primeira vez, começou a calcular também o que uma vitória isolada podia tirar de suas mãos."
]);

addChapter("c10", "X · A Magia no Corpo", [
  "Aos quinze anos, Draven já não confundia a centelha com um truque. Ainda era pequena, comum e difícil de sustentar, mas a magia ocupava o centro da formação que ele queria construir. O treino daquele período combinava gesto, fôlego e deslocamento. A luz precisava permanecer estável enquanto o corpo mudava de ritmo; qualquer excesso era registrado no piso e interrompido pelo instrutor.",
  "Draven começou a prática com a expectativa de atravessar todo o curso. No terceiro marcador, tentou acelerar. A centelha se rompeu e os dedos tremeram. Ele fechou a mão, frustrado, enquanto o painel escuro registrava a interrupção. O salão permanecia cheio de ruídos discretos: os ajustes do mecanismo, os passos dos outros rapazes, uma válvula fechando junto à estação médica.",
  { src: "assets/draven/draven-quinze-anos-pratica.jpg", alt: "Draven aos quinze anos pratica uma luz mágica simples e instável no salão de treino avançado", width: 1122, height: 1402 },
  "— Você está tentando obrigar a luz a acompanhar o orgulho — disse o instrutor.",
  "— E ela está recusando?",
  "— Está mostrando o que você ainda não controla.",
  "Draven detestava respostas que pareciam definitivas. Recomeçou. Desta vez, manteve o passo curto e deixou que a luz oscilasse sem tentar corrigir cada tremor. Chegou ao segundo marcador antes que ela se apagasse. O resultado era modesto. Ele anotou o tempo, comparou com o anterior e marcou o ponto exato em que a respiração começara a quebrar.",
  "A técnica avançada da sala tornava o esforço visível, mas não o realizava por ele. Um conjunto de sensores no piso registrava o ritmo e alimentava o mostrador do instrutor; a estação médica mantinha água, faixas e instrumentos de avaliação à mão. O sistema evitava que um erro pequeno se transformasse numa lesão. Draven aceitava a proteção com a impaciência de quem preferia não precisar dela.",
  "No fim da sessão, pediu mais uma repetição. O instrutor permitiu uma última tentativa. Draven percorreu três marcadores com a luz acesa e encerrou antes de perder o controle. Não tinha vencido ninguém. Mesmo assim, guardou o tempo melhorado e saiu do salão com um plano para a manhã seguinte. A ambição continuava grande; o avanço, não."
]);

addChapter("c11", "XI · Fora do Território", [
  "A visita à estação de distribuição aconteceu fora do território masculino, como parte de uma atividade acompanhada. Draven tinha dezesseis anos e viajou com o guia e outros rapazes. A instalação abastecia casas e oficinas por uma rede de canais protegidos sob a rua. À superfície, tudo parecia simples; por dentro das paredes, válvulas, sensores mecânicos e circuitos de controle mantinham a pressão constante.",
  "Uma técnica jovem recebeu o grupo. Não era guarda nem nobre: vestia um avental de trabalho e sabia de memória quais leituras mudavam com a temperatura. Draven aproximou-se do painel antes que o guia terminasse as apresentações. Ela apontou para uma coluna de valores e explicou a diferença entre um circuito ativo e um fluxo já estabilizado.",
  { src: "assets/draven/draven-dezesseis-anos-visita.jpg", alt: "Draven aos dezesseis anos observa a leitura de uma jovem técnica numa estação urbana avançada", width: 1122, height: 1402 },
  "— Essa luz está verde — disse Draven. — O trecho está liberado.",
  "— A leitura está verde. O trecho ainda não — respondeu ela, apontando a segunda coluna. — Se você abrir a comporta agora, devolve a pressão para a linha de entrada.",
  "Draven inclinou-se para ver o detalhe. A mulher não recuou nem suavizou a explicação. Os rapazes atrás dele esperavam que contestasse. Ele percebeu a diferença entre insistir numa opinião e provar que ela estava errada; naquela leitura, não havia como.",
  "— Então por que o indicador principal acende antes?",
  "— Para avisar que o circuito recebeu energia. Não para adivinhar o que você vai fazer.",
  "A resposta arrancou uma risada curta de um dos colegas. Draven voltou o rosto para ele, mas não comentou. A técnica mudou a posição de duas alavancas e o fluxo se estabilizou. Não fez discurso sobre a importância do seu trabalho. Apenas passou para a próxima verificação.",
  "Durante a visita, Draven observou a equipe acompanhar leituras em vários pontos, comparar desvios e acionar manutenção antes que a água chegasse às casas. A infraestrutura não dependia de uma pessoa brilhante. Dependia de método, comunicação e gente capaz de corrigir um ao outro sem perder tempo para provar quem mandava.",
  "Ao deixar a estação, Draven fez uma pergunta sobre a formação técnica dela. A jovem respondeu que aprendera com prática e estudo, e que ainda tinha muito a aprender. Ele reconheceu a frase — era a mesma conclusão que odiava ouvir sobre si próprio. Dessa vez não a contestou."
]);

addChapter("c12", "XII · Um Convite, Um Limite", [
  "Quando a visita terminou, o grupo se reuniu perto da praça de serviço enquanto o guia conferia o horário do transporte. Draven percebeu que a técnica ainda conversava com duas colegas, fechando os registros do turno. Gostara de vê-la segura diante dos mecanismos e das perguntas; também gostara do modo como ela não tentava agradá-lo.",
  "Ele esperou até que ela terminasse de guardar as ferramentas. Então ofereceu um sorriso que usava quando queria parecer mais experiente do que se sentia.",
  { src: "assets/draven/draven-dezesseis-anos-limite.jpg", alt: "Draven aceita a recusa da jovem técnica e se afasta com constrangimento contido", width: 1122, height: 1402 },
  "— Se já terminou por hoje, posso acompanhar você até a rua principal.",
  "Ela agradeceu, mas recusou. Queria fechar o turno com as colegas e não tinha interesse em sair com ele. A resposta foi clara, sem crueldade e sem convite escondido.",
  "Draven sentiu o rosto aquecer e procurou uma frase que recuperasse a vantagem. Encontrou várias; nenhuma melhorava a situação. Respirou, abriu espaço entre os dois e assentiu.",
  "— Entendido. Boa noite, então.",
  "Ela respondeu com um gesto e voltou ao trabalho. Draven retornou ao grupo. Um dos rapazes ergueu as sobrancelhas, mas ele o cortou antes da primeira pergunta.",
  "— Se vai perguntar, poupe o fôlego.",
  "A tentativa não o tornou romântico nem arrependido por sentir interesse. Ele continuava atraído pela segurança dela e irritado por não ter conseguido conduzir a conversa como conduzia uma disputa. Mas a resposta dela não era uma barreira a vencer. Era uma resposta.",
  "No transporte de volta, Draven passou o polegar pela faixa carmesim na alça da bolsa. Lembrou-se das cartas da mãe, que falavam de gosto como escolha, não como obrigação. A associação não resolveu seu constrangimento. Apenas lhe deu uma maneira de guardá-lo sem transformá-lo em ressentimento.",
  "Quando regressou ao território masculino, deixou a faixa no lugar. Não contou aos outros rapazes o que quase dissera. Na manhã seguinte, treinou magia como sempre: mãos abertas, fôlego medido, luz pequena. A vida não lhe devia um sim, e o treino não lhe devia uma vitória. Ele ainda queria ambas as coisas. Teria de aprender a conquistá-las sem fingir que lhe pertenciam."
]);

addChapter("c13", "XIII · A Travessia", [
  "Aos dezesseis anos, Draven acompanhou um pequeno grupo até uma garganta arborizada, onde uma rota de transporte ligava comunidades separadas por um curso de água. A visita era supervisionada. O guia explicou que o sistema suspenso estava em revisão depois de uma sequência de chuvas; a travessia só abriria quando as leituras estivessem dentro dos limites seguros.",
  "A estrutura era antiga na forma e precisa no funcionamento. A pedra sustentava trilhos de metal escuro; cabos reforçados corriam por dentro de arcos e os contrapesos se moviam em câmaras fechadas. Um painel com pequenas luzes indicava o estado de cada trecho. A manutenção não dependia de adivinhação: os técnicos comparavam pressão, tensão e desgaste antes de autorizar a passagem.",
  { src: "assets/draven/draven-dezesseis-anos-travessia.jpg", alt: "Draven aos dezesseis anos observa uma travessia suspensa em revisão, com mecanismos de segurança integrados", width: 1122, height: 1402 },
  "Draven percebeu que o terceiro sinal demorava a estabilizar. Sugeriu que o painel estivesse atrasado. O guia não respondeu de imediato; chamou um técnico, que comparou a leitura central com dois instrumentos laterais. O dado estava correto. O movimento da água ainda fazia oscilar a tensão de um cabo.",
  "— A gente podia atravessar a pé pela passarela — disse Draven.",
  "— Poder, pode. A questão é se deve — respondeu o guia.",
  "Draven olhou para o vão, depois para a marca de segurança no piso. Não gostava de esperar quando enxergava uma solução; gostava ainda menos de ser lembrado de que talvez não tivesse entendido o problema. Ficou junto aos outros rapazes enquanto os técnicos ajustavam a tensão e repetiam a leitura.",
  "A primeira sequência de luzes mudou. A segunda, não. O sistema permaneceu fechado. Draven acompanhou o procedimento sem interferir, memorizando quais sinais os adultos verificavam antes de liberar o mecanismo. Quando finalmente atravessaram, o transporte seguiu devagar e cada trava confirmou a seguinte.",
  "Do outro lado, a floresta escondia canais de drenagem, estações de manutenção e pequenas casas de serviço. Draven encontrou uma marca que indicava uma válvula secundária e perguntou por que ela ficava fora do painel principal. O técnico explicou que, se a rede inteira dependesse de um único ponto, qualquer pane isolaria as comunidades. Draven anotou a resposta no caderno.",
  "A travessia não lhe dera um feito para contar. Deu-lhe a lembrança de que uma máquina confiável dependia de redundância, leitura cuidadosa e gente disposta a esperar. Ele continuava preferindo agir primeiro. Pela primeira vez, considerou que saber quando não agir também podia ser uma forma de competência."
]);

addChapter("c14", "XIV · Sem Controle", [
  "No ano seguinte, Draven e o colega dos exercícios voltaram a treinar juntos. Tinham crescido o bastante para que as antigas disputas parecessem menores, mas nenhum dos dois fingia que a competição havia desaparecido. O exercício em dupla exigia manter uma luz comum entre as mãos enquanto alternavam o ritmo de caminhada. Um iniciava; o outro estabilizava. Depois trocavam.",
  "Draven pediu para começar. O colega aceitou, com a condição de escolher a sequência seguinte. Draven concordou. Não era um acordo de amizade. Era uma regra clara para que nenhum deles pudesse transformar a prática numa exibição solo.",
  { src: "assets/draven/draven-dezessete-anos-parceria.jpg", alt: "Draven e o colega aos dezessete anos mantêm uma luz mágica simples durante um exercício cooperativo", width: 1122, height: 1402 },
  "Na primeira rodada, Draven acelerou quando a luz do colega começou a oscilar. O sinal entre eles falhou e a centelha se apagou. Draven cerrou os dentes.",
  "— Você mudou o ritmo.",
  "— Você não esperou o sinal.",
  "O colega tinha razão. Draven poderia culpar o piso ou a resposta tardia. Em vez disso, pediu para repetir. Na segunda tentativa, deixou o outro marcar o passo até receber o sinal. A luz dele permaneceu fraca, mas estável. Quando trocaram as posições, o colega ajustou o ritmo ao de Draven.",
  "Concluíram a sequência sem apagar a luz. O mostrador registrou um tempo mediano e nenhuma interrupção. Draven não comemorou. O colega também não. O resultado pertencia aos dois, o que o tornava menos satisfatório e, de algum modo, mais difícil de descartar.",
  "— Na próxima, tentamos uma marca a mais — disse Draven.",
  "— Se a leitura permitir.",
  "Draven soltou um riso curto. A resposta não era submissão nem desafio. Era só a condição real do exercício. Ele concordou e anotou o tempo. Continuava querendo superar o colega; começava a entender que, naquele tipo de prática, a vitória podia depender de deixar outra pessoa determinar o próximo passo."
]);

addChapter("c15", "XV · Relatos da Oamem", [
  "Aos dezessete anos, Draven ouviu o nome Oamem numa transmissão pública recebida por um relé de comunicação fora do território. O relato era curto e incompleto: comunidades vulneráveis haviam perdido controle sobre áreas e recursos depois de ações da organização. Não informava quem comandava a operação, onde ocorrera nem qual seria a resposta. Não havia motivo para transformar uma notícia parcial em plano de ação.",
  "O guia deixou o registro disponível para consulta e voltou às tarefas do dia. Draven ficou diante do painel. A informação seguinte repetia um rumor antigo: alguns associavam Oamem a Sondark. O dado conhecido era outro. A organização não fora fundada por ele, não pertencia à família Dark e não falava em nome dela. Alguns Dark haviam aderido individualmente; isso não convertia escolha pessoal em mandato familiar.",
  { src: "assets/draven/draven-dezessete-anos-relato.jpg", alt: "Draven aos dezessete anos lê um relato público sobre a Oamem num relé de comunicação, sem símbolos da organização", width: 1122, height: 1402 },
  "Draven releu as duas linhas e fechou o relatório. Não precisava decidir naquele instante o que faria com aquilo. Ainda assim, a mistura de conquista, exploração e rumor o incomodou. O nome de uma família não tornava justa uma ação; tampouco uma ligação individual transformava toda a linhagem em responsável.",
  "— Vai responder? — perguntou um dos rapazes.",
  "— A quem?",
  "— Ao relatório.",
  "Draven apontou para a linha que dizia que os dados eram incompletos. Não havia destinatário, endereço de contato ou pedido de ajuda. Havia uma notícia, não uma convocação. Ele não queria tratar a distância como desculpa, mas também não confundia indignação com conhecimento.",
  "No caderno, escreveu três perguntas: o que fora confirmado, o que era rumor e quem ganhava com a associação a Sondark. Não anotou um juramento, uma missão ou uma promessa de vingança. A decisão de como Draven reagiria a Oamem continuava aberta para a campanha; naquela noite, ficou apenas o incômodo de ver o nome Dark usado como atalho para legitimar algo que não representava a família.",
  "Quando o relé se apagou, Draven voltou ao treino. A luz simples entre as mãos falhou duas vezes antes de se firmar. Ele não a confundiu com uma resposta para o mundo. Era só o exercício da tarde, pequeno e incompleto — exatamente o tipo de trabalho que ainda podia fazer."
]);

addChapter("c16", "XVI · Marcas Escolhidas", [
  "Aos dezoito anos, Draven já reconhecia a própria mão em alguns detalhes: o fecho carmesim escolhido por ele, o corte mais limpo das mangas e o modo como combinava peças Dark com linhas que lembravam as imagens das cartas da mãe. O cabelo, antes solto até os ombros, agora chegava às costas; uma trança estreita começava a manter os fios fora do rosto. Não copiara um traje alheio. Separara o que lhe agradava e deixara o restante onde estava.",
  "Naquela tarde, voltou a uma carta antiga. A mãe descrevia padrões que conhecera na infância, em tecidos, cerâmicas e objetos de uso diário. Nunca os apresentava como regra para o filho. No fim, escrevera que uma imagem podia atravessar gerações sem se tornar obrigação. Draven releu a frase, dobrou o papel no vinco antigo e guardou-o junto às referências que reunira ao longo dos anos.",
  "As folhas não formavam um catálogo de uma cultura inteira. Eram escolhas fragmentárias: curvas, escamas, pétalas, garras e espaços vazios que ele destacara porque gostava de observá-los. Algumas vinham das cartas; outras, de gravuras encontradas em viagens acompanhadas. O que as unia não era uma mensagem herdada, mas o olhar insistente de Draven, que voltava às mesmas formas até saber quais queria carregar.",
  "Entre as figuras, separou duas. O demônio ficaria nas costas: aquilo que não precisava mostrar para saber que carregava — orgulho, determinação e a disposição implacável de encarar o que o intimidava. O dragão ocuparia a parte frontal: não uma conquista já alcançada, mas a grandeza e a liberdade que desejava perseguir por esforço próprio. Nenhuma figura lhe prometia força. Nenhuma respondia por Sondark, pela família ou por um destino. Eram símbolos pessoais, escolhidos por um jovem que ainda não havia chegado ao topo.",
  "A decisão de marcar o corpo foi dele. Não houve rito, juramento, desafio familiar ou conselho que pudesse substituí-la. Draven escolheu uma oficina fora do território exclusivamente masculino, reuniu as referências numa pasta e saiu sem pedir que alguém aprovasse o motivo. O trajeto pela cidade pareceu mais longo do que lembrava. Pela primeira vez, a escolha não seria medida por um instrutor nem registrada num mostrador.",
  "O artista recebeu Draven numa sala de trabalho iluminada por uma janela alta. Instrumentos finos descansavam em estojo de madeira; uma lente articulada e uma pequena lâmpada regulável completavam a bancada sem transformar o lugar num laboratório. O artista não perguntou sobre linhagem ou magia. Perguntou onde Draven queria começar e quanto tempo estava disposto a reservar.",
  "Draven espalhou os papéis. Apontou o que queria manter, o que devia ser simplificado e os trechos em que uma linha precisava respirar. O artista sugeriu ajustes para que as formas acompanhassem o movimento do corpo. Draven recusou duas propostas, aceitou uma terceira e ficou algum tempo em silêncio diante do desenho das costas.",
  "— Esse fica atrás — disse, por fim. — Não precisa ser visto para estar comigo.",
  "Depois tocou a folha do dragão. — E este vai à frente. Ainda é para onde eu quero chegar.",
  "O artista não tratou aquilo como profecia. Apenas refez a escala e mostrou como o conjunto poderia acompanhar ombros e peito sem interromper o movimento. Draven aprovou quando reconheceu no papel a composição que escolhera, não uma promessa que outra pessoa tivesse inventado para ele.",
  "A primeira sessão começou pelo braço. Draven manteve a mão aberta sobre o apoio e observou o trabalho sem fingir que o desconforto não existia. Quando o corpo enrijeceu, pediu uma pausa; depois voltou ao lugar. A linha inicial era pequena e incompleta, parte de um desenho maior. A tinta assentava aos poucos, com o artista conferindo o traço antes de avançar.",
  "As horas seguintes trouxeram pausas, água, tecido limpo e novas posições. Os braços e antebraços receberam as primeiras extensões da composição, sem que cada trecho precisasse ser explicado em voz alta. Draven corrigiu uma curva, ouviu a justificativa técnica e aceitou o ajuste quando percebeu que a forma acompanharia melhor o cotovelo. Sua teimosia não o impediu de distinguir uma preferência de um bom conselho profissional.",
  "Para o desenho das costas, deitou-se de bruços e deixou que o artista trabalhasse por partes. A figura não nasceu num único gesto. Cada sessão acrescentava linhas e sombras, enquanto o resto permanecia coberto por tecido. Draven suportava o incômodo em silêncio, mas não o transformava em espetáculo. O demônio era aquilo que carregava; não era uma criatura, uma herança ou uma fonte de poder.",
  "O dragão veio depois, na parte frontal, com o corpo protegido por uma cobertura e apenas a área necessária exposta ao trabalho. Draven acompanhou os traços no espelho inclinado quando o artista permitiu. A imagem parecia avançar em direção aos ombros, mas continuava sendo tinta sobre pele. Grandeza, liberdade e domínio do próprio destino eram objetivos — não resultados antecipados.",
  "Nas sessões finais, o desenho conectou braços, ombros, peito e pescoço segundo a composição original que Draven havia aprovado. As referências maternas permaneceram como parte de sua história, não como uma ordem. O artista limpou a pele, revisou cada linha e explicou os cuidados para a cicatrização. Draven ouviu sem impaciência; naquela ocasião, obedecer às instruções era uma forma de proteger uma decisão sua.",
  { src: "assets/draven/draven-c16-braco-proporcao-corrigida-2026.webp", alt: "Aos dezoito anos, Draven avalia as tatuagens pessoais concluídas com proporções naturais; a composição oficial permanece a escolhida por ele", width: 1122, height: 1402 },
  "Quando viu o conjunto inteiro, Draven não procurou nele um sinal de que já tivesse vencido alguma coisa. Reconheceu duas direções: o que levava consigo e aquilo que ainda queria alcançar. As marcas não tornavam sua magia mais forte, não o ligavam a uma profecia e não encerravam a disputa com os próprios limites. Apenas tornavam visível uma decisão que já era sua.",
  "Na volta, guardou a carta da mãe no mesmo compartimento da pasta. Não contou aos colegas do território o que cada linha significava. Se perguntassem, diria que escolhera os desenhos porque gostava deles — e, se insistissem, talvez dissesse que um lembrava o peso que carregava e o outro a distância que ainda queria percorrer. Era o bastante. As cartas continuavam sendo da mãe; o corpo e a escolha eram dele."
]);

addChapter("c17", "XVII · O Limiar", [
  "Aos dezenove anos, Draven voltou ao salão de avaliação para uma última sequência antes de deixar a rotina de formação. Não havia cerimônia nem prova secreta. O instrutor organizou um percurso comum: deslocamento, leitura de sinais, uma aplicação simples de magia e uma tarefa de precisão. Os mostradores registrariam o que acontecesse, sem transformar o exercício num veredito sobre o futuro.",
  "Draven começou rápido demais e perdeu o primeiro sinal. O instrutor mandou reiniciar. Ele apertou a mandíbula, mas voltou à marca inicial. Na segunda tentativa, leu o painel, ajustou a respiração e concluiu o trecho sem exceder o limite indicado. A magia surgiu como uma luz pequena e instável; sustentou-a por alguns passos, perdeu a forma e precisou começar de novo.",
  { src: "assets/draven/draven-dezenove-anos-limiar.jpg", alt: "Draven aos dezenove anos conclui uma avaliação comum com magia simples, ainda iniciante", width: 1122, height: 1402 },
  "O registro apontou melhora em relação ao ciclo anterior e interrupção na parte mágica. Draven leu as duas linhas. Teria preferido que a primeira apagasse a segunda, mas o papel não se prestava a elogios. Ele anotou o tempo e o erro com a mesma letra firme.",
  "— Ainda acha que devia ter terminado tudo? — perguntou o instrutor.",
  "— Acho que devia ter ido mais longe.",
  "— Isso não responde.",
  "Draven guardou o caderno. Continuava competitivo, ainda impaciente com limites e longe de dominar a magia que escolhera como especialidade. Também sabia reconhecer uma medição honesta. Não precisava chamar um resultado parcial de vitória para continuar querendo melhorar.",
  "Mais tarde, fechou a bolsa. A carta da mãe, o caderno de treino e algumas peças escolhidas por ele ficaram juntos, sem que um item explicasse os demais. As tatuagens permaneceram cobertas pela roupa. Draven não recebeu uma missão, não fez um juramento e não descobriu um poder oculto. Apenas chegou aos dezenove anos com experiência suficiente para saber o que ainda não sabia.",
  "Do lado de fora, a passagem aguardava aberta. Draven parou um instante, olhou para trás e depois seguiu até o limiar. A campanha começaria depois daquele passo. O que ele faria nela ainda não estava escrito."
]);

